package com.harish.student_management.dto;
import lombok.*; import jakarta.validation.constraints.*;
public final class TransportDtos { private TransportDtos(){} @Data public static class BusRequest{@NotBlank public String registrationNumber; public String model; @Positive public Integer capacity; public String status;} @Data public static class DriverRequest{@NotBlank public String name; @NotBlank public String licenseNumber; public String phone,status;} @Data public static class RouteRequest{@NotBlank public String name; public Long busId,driverId; public String status;} @Data public static class PointRequest{@NotNull public Long routeId; @NotBlank public String name; public String address; public Integer sequence; public String pointType;} @Data public static class AllocationRequest{@NotNull public Long studentId,busId,routeId,pickupPointId,dropPointId; public String status;} }
